const event = $input.first()?.json;
if (!event) return [];
const text = String(event.text_content ?? '').trim();
const command = text.toLowerCase().split(/\s+/)[0] || null;
const known = new Set(['/start','/comandos','/ajuda','/menu','/status','/progresso','/protocolo','/pendencias','/duvidas','/excluir','/excluirultimo','/confirmar','/pobj','/metas','/prioridades','/riscos','/cenarios','/indicador','/historico','/fontes','/evidencias','/hoje','/corrigir','/responder','/reabrir','/explicar','/privacidade','/meusdados']);
return [{json:{...event, route: known.has(command) ? 'COMMAND' : event.event_kind === 'DOCUMENT' || event.event_kind === 'IMAGE' ? 'DOCUMENT' : 'CONVERSATION', command, runtime:'N8N_LOCAL', business_state:'POSTGRES_VISAO360'}}];
